class Solution:
    def countPrimes(self, n: int) -> int:
        if n < 3:
            return 0
        is_prime = [True] * n
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(n ** 0.5) + 1):
            if is_prime[p]:
                for m in range(p * p, n, p):     # smaller multiples were crossed out already
                    is_prime[m] = False
        return sum(is_prime)
